const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let questions=[];let language='EN',scenario='normal',staff=true,selectedFlight=null,pending=null,messages=[],traces=[],activeOps='traces';
