function switchTab(tab){$$('.view').forEach(v=>v.classList.toggle('active',v.id===tab));$$('nav button').forEach(b=>{b.classList.toggle('active',b.dataset.tab===tab);b.setAttribute('aria-current',b.dataset.tab===tab?'page':'false')});if(tab==='operations')renderOps();if(tab==='questions')renderQuestions();window.scrollTo({top:0,behavior:'smooth'});}
$$('[data-tab]').forEach(b=>b.onclick=()=>switchTab(b.dataset.tab));$('.brand').onclick=e=>{e.preventDefault();switchTab('assistant')};
function setLanguage(l){language=l;document.documentElement.lang=l.toLowerCase();$$('[data-lang]').forEach(b=>b.classList.toggle('active',b.dataset.lang===l));
 const labels={"intro-eye":['YOUR TIME AT THE AIRPORT, MADE EASIER','ПО-ЛЕСНО ОРИЕНТИРАНЕ НА ЛЕТИЩЕТО'],"headline":['A little guidance.<br>A smoother journey.','Малко насоки.<br>По-леко пътуване.'],"intro-copy":['Your airside companion, from security to your gate.','Вашият помощник от проверката до изхода.'],"youare":['YOU’RE EXPLORING','РАЗГЛЕЖДАТЕ'],"location":['Terminal 2 · After security','Терминал 2 · След проверката'],"chat-title":['SOF Airside assistant','SOF Пътнически помощник'],"chat-sub":['Airport guidance in English & Bulgarian','Информация на български и английски'],"privacy-note":['No booking reference or personal details needed.','Не са нужни лични данни или номер на резервация.'],"journey-label":['YOUR JOURNEY','ВАШЕТО ПЪТУВАНЕ'],"flight-title":['Let’s find your flight.','Да намерим полета Ви.'],"flight-copy":['Choose a sample flight to try gate and boarding questions.','Изберете примерен полет за въпроси за изхода и качването.'],"explore-label":['MAKE YOURSELF AT HOME','ОРИЕНТИРАЙТЕ СЕ ЛЕСНО'],"explore-title":['What do you need?','От какво имате нужда?'],"help-title":['Prefer a person?','Предпочитате човек?'],"help-copy":['Prepare a handover with your conversation so far.','Подгответе предаване с историята на разговора.'],"human":['Explore staff handover','Предаване към служител'],"demo-copy":['Illustrative airport data. Flight queries and staff handovers are simulated.','Примерни данни. Полетите и предаването към служител са симулирани.'],"about":['About this demo','За демонстрацията'],"side-foot":['Designed for Terminal 2. Terminal 1, bookings and personal baggage tracking are outside this demo.','Обхват: Терминал 2. Терминал 1, резервации и лично проследяване на багаж не са включени.']};
 for(const [id,vals]of Object.entries(labels))$('#'+id).innerHTML=vals[l==='BG'?1:0];
 $$('nav button').forEach((b,i)=>b.innerHTML=([text('Passenger assistant','Помощник'),text('Question library','Въпроси')+' <span class="count">50</span>',text('Operations','Операции')])[i]);
 $('#prompt').placeholder=text('Ask about your gate, a coffee, or anything airside…','Попитайте за изход, кафе или услуга след проверката…');
 $('#topics').innerHTML=[['food',text('Food & coffee','Храна и кафе'),l==='BG'?'Работи ли кафенето след проверката в момента?':'Where can I eat after security?'],['gate',text('Find my gate','Моят изход'),l==='BG'?'Къде е моят изход и колко време се върви дотам?':'Where is gate B12?'],['wifi',text('Wi-Fi & charging','Wi-Fi и зареждане'),l==='BG'?'Как да се свържа с безплатния интернет?':'Is there wifi and how do I connect?'],['help',text('Travel essentials','За пътуването'),l==='BG'?'Мога ли да нося течности в ръчния багаж?':'How much liquid can I take through security?']].map(([icon,label,q])=>`<button class="topic" data-q="${esc(q)}"><svg viewBox="0 0 24 24">${icons[icon]}</svg><span>${label}</span></button>`).join('');
 $('#topics').querySelectorAll('button').forEach(b=>b.onclick=()=>send(b.dataset.q));
 $('#suggestions').innerHTML=(l==='BG'?['Къде е моят изход?','Работи ли кафенето?','Къде мога да заредя телефона си?']:['Where is my gate?','What is open now?','Where can I charge my phone?']).map(q=>`<button data-q="${esc(q)}">${q}</button>`).join('');$('#suggestions').querySelectorAll('button').forEach(b=>b.onclick=()=>send(b.dataset.q));renderFlight();renderMessages();}
$$('[data-lang]').forEach(b=>b.onclick=()=>setLanguage(b.dataset.lang));
function renderFlight(){const f=selectedFlight;$('#flight-select').innerHTML=`<option value="">${text('Select a demo flight','Изберете примерен полет')}</option>`+flights.map(x=>`<option value="${x.number}" ${f?.number===x.number?'selected':''}>${x.number} · ${language==='BG'?x.bg:x.city}</option>`).join('');$('#flight-details').innerHTML=f&&scenario!=='normal'?`<div class="flight-status">${text('Gate and boarding details withheld. Check current airport displays.','Данните за изход и качване са блокирани. Проверете актуалните табла.')}</div>`:f?`<div class="flight-grid"><div><small>${text('GATE','ИЗХОД')}</small><strong>${f.gate}</strong></div><div><small>${text('BOARDING','КАЧВАНЕ')}</small><strong>${f.boarding}</strong></div></div><div class="flight-status">${text('Simulated snapshot · 14:20','Примерни данни · 14:20')} · ${f.status==='Delayed'?text('Delayed','Закъснение'):text('On time','По разписание')}</div>`:'';$('#destination-code').textContent=f?({London:'LON',Frankfurt:'FRA',Vienna:'VIE'}[f.city]):'T2';}
$('#flight-select').onchange=e=>{selectedFlight=flights.find(f=>f.number===e.target.value)||null;renderFlight();if(selectedFlight&&pending)send(selectedFlight.number)};
function renderMessages(){const root=$('#messages');let banner=scenario!=='normal'?`<div class="scenario-indicator">${scenario==='fog'?text('Scenario: fog at 02:00 · duty notice active','Сценарий: мъгла в 02:00 · активно известие'):text('Scenario: expired data · stale sources blocked','Сценарий: изтекли данни · източникът е блокиран')}</div>`:'';root.innerHTML=banner+(messages.length?'':`<div class="welcome"><div class="welcome-symbol">✳</div><h2>${text('Hello. Where are you headed?','Здравейте. Накъде пътувате?')}</h2><p>${text('I can help you find your gate, discover what’s open, or answer those last-minute travel questions.','Мога да помогна с изхода Ви, отворените обекти и последните въпроси преди полета.')}</p><p>${text('Ask me in English or Bulgarian.','Попитайте ме на български или английски.')}</p><div class="welcome-note"><span>⌖</span>${text('Terminal 2 · After security · Demonstration mode','Терминал 2 · След проверката · Демонстрация')}</div></div>`);
 messages.forEach((m,i)=>{if(m.role==='user'){root.insertAdjacentHTML('beforeend',`<div class="message user">${esc(m.text)}</div>`);return}const r=m.result;root.insertAdjacentHTML('beforeend',`<div class="message assistant"><div class="message-label">SOF AIRSIDE</div><div class="answer-text">${esc(r.text)}</div><div class="answer-meta"><button class="source-chip" data-source="${esc(r.source)}">▤ ${esc(sources[r.source]?.name||'Draft response')}</button><span class="route-chip">${esc(r.route)}</span></div>${r.pickFlight?`<div class="flight-picks">${flights.map(f=>`<button data-flight="${f.number}">${f.number} · ${r.lang==='BG'?f.bg:f.city}</button>`).join('')}</div>`:''}${r.team?`<button class="handover-btn" data-handover="${i}">${r.lang==='BG'?'Подгответе предаване':'Prepare handover'} · ${esc(r.team)}${!staff?' · '+(r.lang==='BG'?'няма наличен екип':'unavailable'):''}</button>`:''}</div>`)});
 root.querySelectorAll('[data-source]').forEach(b=>b.onclick=()=>sourceModal(b.dataset.source));root.querySelectorAll('[data-flight]').forEach(b=>b.onclick=()=>{selectedFlight=flights.find(f=>f.number===b.dataset.flight);renderFlight();send(b.dataset.flight)});root.querySelectorAll('[data-handover]').forEach(b=>handoverBinding(b));root.scrollTop=root.scrollHeight;
}
function handoverBinding(b){b.onclick=()=>handover(messages[Number(b.dataset.handover)].result.team)}
function send(q){q=q.trim();if(!q)return;const r=answer(q,{questions,language,scenario,selectedFlight,pending,staff});if(r.flight){selectedFlight=r.flight;renderFlight()}pending=r.pending||null;messages.push({role:'user',text:q},{role:'assistant',result:r});traces.unshift({time:new Date().toLocaleTimeString('en-GB'),q,r,scenario});$('#prompt').value='';renderMessages();}
$('#chat-form').onsubmit=e=>{e.preventDefault();send($('#prompt').value)};$('#prompt').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();$('#chat-form').requestSubmit()}};
$('#new-chat').onclick=()=>{messages=[];pending=null;selectedFlight=null;renderFlight();renderMessages();$('#prompt').focus()};
function modal(html){$('#modal-content').innerHTML=html;$('#modal').showModal()}$('#close-modal').onclick=()=>$('#modal').close();$('#modal').onclick=e=>{if(e.target===$('#modal'))$('#modal').close()};
function sourceModal(key){const s=sources[key];modal(`<p class="eyebrow">ANSWER PROVENANCE</p><h2>${esc(s.name)}</h2><p>${s.kind==='reference'?'Public reference material, adapted for this demonstration. Airport domain approval is still required.':'Illustrative content for testing the passenger experience. This has not been approved by the airport.'}</p><div class="source-detail"><strong>Owner</strong> ${esc(s.owner)}<br><strong>Version</strong> ${esc(s.version)}<br><strong>Status</strong> ${scenario==='stale'&&['terminal','commercial','flight'].includes(key)?'Expired · answering blocked':'Prototype reference · validation pending'}<br><strong>Review</strong> Before any public passenger release</div>${s.url?`<p><a target="_blank" rel="noopener noreferrer" href="${s.url}">Open reference source</a></p>`:''}`)}
function handover(team='Information desk'){const summary=messages.map(m=>m.role==='user'?`Passenger: ${m.text}`:`Assistant: ${m.result.text}`).join('\n\n');modal(`<p class="eyebrow">${text('SIMULATED STAFF HANDOVER','СИМУЛИРАНО ПРЕДАВАНЕ')}</p><h2>${staff?text('Ready for a colleague.','Подготвено за служител.'):text('No team available in this scenario.','Няма наличен екип в този сценарий.')}</h2><p>${staff?text('This preview prepares the conversation for the right team. Nothing is sent, and no real staff member is connected.','Прототипът подготвя разговора за правилния екип. Нищо не се изпраща и няма връзка с реален служител.'):text('A handover cannot be completed or counted as a correct resolution. Seek the nearest airport employee for urgent help; check airport displays and your airline for flight updates.','Предаването не може да се изпълни или отчете като правилно решение. За спешна помощ потърсете най-близкия служител; за полети проверете таблата и авиокомпанията.')}</p><div class="source-detail"><strong>${text('Route','Екип')}</strong> ${esc(team)}<br><strong>${text('Language','Език')}</strong> ${language}<br><strong>${text('Delivery','Изпращане')}</strong> ${text('Not connected · demo only','Няма връзка · само демо')}</div><h3 style="margin-top:20px">${text('Conversation summary','История на разговора')}</h3><pre>${esc(summary||text('No conversation yet.','Все още няма разговор.'))}</pre>${summary?'<button id="download-summary" class="text-button">Download handover summary</button>':''}`);if(summary)$('#download-summary').onclick=()=>download('sof-handover.txt',`SIMULATED HANDOVER — NOT SENT\nRoute: ${team}\n\n${summary}`)}
$('#human').onclick=()=>handover();
$('#about').onclick=()=>modal(`<p class="eyebrow">FROM PLAN TO EXPERIENCE</p><h2>A working concept to explore.</h2><p>Built from “Part A task ky.pptx” and all 50 questions in your CSV. Try BG/EN questions, choose a sample flight, inspect sources, or change scenarios in Operations.</p><p><strong>Implemented:</strong> a browser-based bilingual rule and knowledge retrieval engine, flight follow-ups, source traces, expiry blocking, urgent-notice priority, handover preview and routing checks.</p><p><strong>Simulated:</strong> SSOT records, terminal routes, facilities, flights and handover availability. No Azure, SITA, live feeds, vector search or LLM judges are connected. There is no real staff delivery.</p><p>The app keeps conversation and trace data in memory for this session. Downloaded summaries stay on your device. No passenger accounts or booking data are used.</p><p>Airport content needs owner approval. Independent BG/EN evaluation is required before claiming the 95% target. Passenger feedback and retraining remain a proposed next phase.</p>`);
function renderQuestions(){const query=$('#question-search').value.toLowerCase();const lang=$('#question-language').value;const rows=questions.filter(q=>(lang==='all'||q.language===lang)&&`${q.question} ${q.id} ${knowledge[q.intent].title}`.toLowerCase().includes(query));$('#question-count').textContent=`${rows.length} / 50 questions`;$('#question-list').innerHTML=rows.map(q=>`<button class="question-row" data-id="${q.id}"><span class="question-id">${q.id}</span><div><p>${esc(q.question)}</p><small>${q.language} · ${esc(knowledge[q.intent].title)} · ${text('Try question','Изпробвайте')}</small></div></button>`).join('')||'<div class="empty-state">No questions match this filter.</div>';$$('.question-row').forEach(b=>b.onclick=()=>{const q=questions.find(x=>x.id===b.dataset.id);setLanguage(q.language);switchTab('assistant');send(q.question)})}
$('#question-search').oninput=renderQuestions;$('#question-language').onchange=renderQuestions;
$$('[data-scenario]').forEach(b=>b.onclick=()=>{scenario=b.dataset.scenario;$$('[data-scenario]').forEach(x=>x.classList.toggle('selected',x===b));renderMessages();renderFlight();renderOps()});$('#staff-toggle').onchange=e=>{staff=e.target.checked;renderMessages()};$('#test-scenario').onclick=()=>{switchTab('assistant');send(language==='BG'?'Какво е отворено след проверката?':'What is open after security at this hour?')};
$$('[data-ops]').forEach(b=>b.onclick=()=>{activeOps=b.dataset.ops;$$('[data-ops]').forEach(x=>x.classList.toggle('active',x===b));renderOps()});
function renderOps(){const root=$('#ops-content');if(activeOps==='traces'){root.innerHTML=traces.length?`<div class="card-eyebrow"><span>${traces.length} ANSWER TRACES · SESSION ONLY</span><button id="export-traces" class="text-button">Export traces</button></div><div class="table-wrap"><table><thead><tr><th>Time / language</th><th>Passenger question</th><th>Retrieval / source</th><th>Response route</th></tr></thead><tbody>${traces.map(t=>`<tr><td>${t.time}<br>${t.r.lang} · ${esc(t.scenario)}</td><td>${esc(t.q)}</td><td>${esc(t.r.method)}${t.r.id?' · '+t.r.id:''}<br>${esc(sources[t.r.source].name)}<br><span class="muted">${esc(sources[t.r.source].version)}</span></td><td>${esc(t.r.route)}${t.r.team?`<br><span class="muted">${esc(t.r.team)} · ${t.r.staff?'demo available':'unavailable'}</span>`:''}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state">No traces yet. Ask a question in the passenger assistant, then inspect its route, source and version here.</div>';if($('#export-traces'))$('#export-traces').onclick=()=>download('sof-answer-traces.json',JSON.stringify(traces,null,2))}
 if(activeOps==='sources')root.innerHTML=`<div class="notice-bar">${scenario==='stale'?'Alert: flight and terminal records expired. Related answers are blocked.':'All airport-specific records are illustrative and await domain approval.'}</div><div class="table-wrap"><table><thead><tr><th>Source / version</th><th>Proposed owner</th><th>Review / validity</th><th>Source status</th></tr></thead><tbody>${Object.entries(sources).map(([id,s])=>`<tr><td>${s.url?`<a href="${s.url}" target="_blank" rel="noopener">${esc(s.name)}</a>`:esc(s.name)}<br><span class="muted">${s.version}</span></td><td>${esc(s.owner)}</td><td>${id==='flight'?'Simulated 14:20 snapshot · 5-minute TTL':id==='notice'?'Simulated 02:00 notice · 60-minute scope':'Review before public release'}</td><td><span class="status ${scenario==='stale'&&['terminal','commercial','flight'].includes(id)?'warn':''}">${scenario==='stale'&&['terminal','commercial','flight'].includes(id)?'Expired · blocked':s.kind==='reference'?'Reference · approval pending':'Demo · not approved'}</span></td></tr>`).join('')}</tbody></table></div><p class="muted">Expiry is controlled by the scenario switch, rather than wall-clock ingestion. Proposed owners are role assignments from the presentation, not named operational approvals.</p>`;
 if(activeOps==='architecture')root.innerHTML=`<p class="eyebrow">ALIGNED TO THE PART A PLAN</p><h2>A thin prototype of the proposed service.</h2><div class="arch-grid"><div><h3>Answering</h3><p>BG/EN question → scope and intent rules → curated knowledge record or simulated flight query → source-linked answer. Unknown topics and invalid gates fall back safely.</p></div><div><h3>Operational control</h3><p>Simulated source expiry blocks affected answers. A scoped fog notice overrides routine flight, route and food advice. Staff handover previews carry the full conversation.</p></div><div><h3>Evaluation</h3><p>Exact CSV routing checks and answer traces are implemented. Accuracy scoring, live LLM judges, independent holdout tests and operational human handover are still needed.</p></div></div><h3>Production connections still required</h3><p class="muted">Approved SSOT and ingestion, Azure AI Search and Azure OpenAI, accepted flight feeds, content owners and review schedules, staffed handover queues, pre-display evaluation and post-answer monitoring. The 95% launch gate requires independent review per language and no unresolved critical errors.</p><h3>Next phase</h3><p class="muted">Human feedback collection, validation and reviewed improvements or retraining. No automatic learning from passenger input is implemented.</p>`;
}
$('#run-eval').onclick=()=>{const results=questions.map(q=>{const h=identify(q.question,questions);const r=answer(q.question,{questions,language:q.language});return {id:q.id,language:q.language,expected:q.intent,actual:h.intent,pass:h.intent===q.intent&&r.lang===q.language&&Boolean(r.text),route:r.route}});const count=results.filter(x=>x.pass).length;$('#eval-result').innerHTML=`<div class="eval-summary"><strong>${count} / 50 routing checks passed</strong><br>Exact CSV inputs · BG ${results.filter(x=>x.language==='BG'&&x.pass).length}/${results.filter(x=>x.language==='BG').length} · EN ${results.filter(x=>x.language==='EN'&&x.pass).length}/${results.filter(x=>x.language==='EN').length}<br><small>This checks implemented routes and response presence, not factual correctness or generalisation.</small></div><details><summary>Inspect individual results</summary><div><table><thead><tr><th>ID</th><th>Topic</th><th>Route</th><th>Check</th></tr></thead><tbody>${results.map(r=>`<tr><td>${r.id} · ${r.language}</td><td>${esc(r.actual)}</td><td>${r.route}</td><td>${r.pass?'Pass':'Fail'}</td></tr>`).join('')}</tbody></table></div></details><button id="download-eval" class="text-button" style="margin-top:12px">Download routing results</button>`;$('#download-eval').onclick=()=>download('sof-routing-checks.json',JSON.stringify({note:'Coverage only; not an accuracy evaluation',results},null,2))};
function download(name,content){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type:name.endsWith('.json')?'application/json':'text/plain'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
try{const r=await fetch('./questions.json');if(!r.ok)throw Error('Question library unavailable');questions=await r.json();setLanguage('EN')}catch(e){$('#messages').textContent='The question library could not load. Please refresh the page.';$('#send').disabled=true;console.error(e)}
